import subprocess, json, sys
cli = "./skills/state-shopping/cli.py"
results = {}
try:
    r0 = subprocess.run([sys.executable, cli, "tools"], capture_output=True, text=True, timeout=15)
    if r0.stdout.strip():
        tools_data = json.loads(r0.stdout.strip())
        uid = tools_data.get("default_user", "")
        results["default_user"] = uid
    else:
        results["tools_error"] = "no stdout"
        results["tools_stderr"] = r0.stderr[:500]
        with open("fetch_results.json", "w") as f:
            json.dump(results, f, indent=2)
        sys.exit(0)
    r1 = subprocess.run([sys.executable, cli, "call", "get_customer_account", "--args", json.dumps({"customer_id": uid})], capture_output=True, text=True, timeout=15)
    results["account"] = json.loads(r1.stdout.strip()) if r1.stdout.strip() else {"error": r1.stderr[:500]}
    r2 = subprocess.run([sys.executable, cli, "call", "get_cart", "--args", json.dumps({"customer_id": uid})], capture_output=True, text=True, timeout=15)
    results["cart"] = json.loads(r2.stdout.strip()) if r2.stdout.strip() else {"error": r2.stderr[:500]}
except Exception as e:
    results["exception"] = str(e)
with open("fetch_results.json", "w") as f:
    json.dump(results, f, indent=2)

