import subprocess, json, sys, sqlite3

cli_shop = "./skills/state-shopping/cli.py"
cli_cs = "./skills/state-customer-support/cli.py"
results = {}

try:
    r0 = subprocess.run([sys.executable, cli_shop, "tools"], capture_output=True, text=True, timeout=15)
    if r0.stdout.strip():
        td = json.loads(r0.stdout.strip())
        uid = td.get("default_user", "")
        results["shopping_user"] = uid
    else:
        uid = None
        results["shop_tools_err"] = r0.stderr[:300]

    if uid:
        r1 = subprocess.run([sys.executable, cli_shop, "call", "get_customer_account", "--args", json.dumps({"customer_id": uid})], capture_output=True, text=True, timeout=15)
        results["shop_account"] = json.loads(r1.stdout.strip()) if r1.stdout.strip() else {"err": r1.stderr[:300]}
        r2 = subprocess.run([sys.executable, cli_shop, "call", "get_cart", "--args", json.dumps({"customer_id": uid})], capture_output=True, text=True, timeout=15)
        results["shop_cart"] = json.loads(r2.stdout.strip()) if r2.stdout.strip() else {"err": r2.stderr[:300]}
except Exception as e:
    results["shop_exc"] = str(e)

try:
    conn = sqlite3.connect("world.db")
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("SELECT user_id, name, email FROM users WHERE name LIKE '%Emma%'")
    results["emma_search"] = [dict(r) for r in cur.fetchall()]
    cur.execute("SELECT user_id, name, email FROM users")
    results["all_users"] = [dict(r) for r in cur.fetchall()]
    conn.close()
except Exception as e:
    results["db_exc"] = str(e)

try:
    r3 = subprocess.run([sys.executable, cli_cs, "tools"], capture_output=True, text=True, timeout=15)
    if r3.stdout.strip():
        cs_td = json.loads(r3.stdout.strip())
        cs_uid = cs_td.get("default_user", "")
        results["cs_default_user"] = cs_uid
        r4 = subprocess.run([sys.executable, cli_cs, "call", "get_customer_profile", "--args", json.dumps({"customer_id": cs_uid})], capture_output=True, text=True, timeout=15)
        results["cs_profile"] = json.loads(r4.stdout.strip()) if r4.stdout.strip() else {"err": r4.stderr[:300]}
except Exception as e:
    results["cs_exc"] = str(e)

with open("all_results.json", "w") as f:
    json.dump(results, f, indent=2)

